"""SQLite-backed durable queue state for incoming GitHub comments."""
from __future__ import annotations
import sqlite3
from dataclasses import dataclass
from pathlib import Path
VALID_STATUSES = {"NEW", "RECEIVED", "PROCESSING", "RESPONDED", "ERROR"}
@dataclass(frozen=True, slots=True)
class QueueItem:
    source_comment_id: str
    issue_number: int
    created_at: str
    content: str
    status: str
    response_comment_id: str | None
    error: str | None
class BridgeState:
    def __init__(self, database_path: str | Path) -> None:
        self.database_path = str(database_path)
        if self.database_path != ":memory:": Path(self.database_path).parent.mkdir(parents=True, exist_ok=True)
        self._connection = sqlite3.connect(self.database_path)
        self._connection.row_factory = sqlite3.Row
        self._connection.execute("PRAGMA foreign_keys = ON")
        self._connection.execute("PRAGMA journal_mode = WAL")
        self._create_schema()
    def _create_schema(self) -> None:
        with self._connection:
            self._connection.execute("""CREATE TABLE IF NOT EXISTS queue_items (source_comment_id TEXT PRIMARY KEY, issue_number INTEGER NOT NULL, created_at TEXT NOT NULL, content TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('NEW','RECEIVED','PROCESSING','RESPONDED','ERROR')), response_comment_id TEXT UNIQUE, error TEXT, inserted_order INTEGER NOT NULL)""")
            self._connection.execute("CREATE INDEX IF NOT EXISTS idx_queue_pending ON queue_items(status, created_at, inserted_order)")
    def enqueue(self, *, source_comment_id: str, issue_number: int, created_at: str, content: str) -> bool:
        if not source_comment_id or not source_comment_id.strip(): raise ValueError("source_comment_id must be non-empty")
        if issue_number <= 0: raise ValueError("issue_number must be positive")
        if not created_at or not created_at.strip(): raise ValueError("created_at must be non-empty")
        if not content or not content.strip(): raise ValueError("content must be non-empty")
        with self._connection:
            cursor = self._connection.execute("""INSERT OR IGNORE INTO queue_items (source_comment_id, issue_number, created_at, content, status, inserted_order) VALUES (?, ?, ?, ?, 'NEW', (SELECT COALESCE(MAX(inserted_order), 0) + 1 FROM queue_items))""", (str(source_comment_id), issue_number, created_at, content))
        return cursor.rowcount == 1
    def get_next_pending(self) -> QueueItem | None:
        row = self._connection.execute("SELECT * FROM queue_items WHERE status IN ('NEW','RECEIVED','ERROR') ORDER BY created_at ASC, inserted_order ASC LIMIT 1").fetchone()
        return self._to_item(row) if row else None
    def get_in_progress(self) -> QueueItem | None:
        row = self._connection.execute("SELECT * FROM queue_items WHERE status = 'PROCESSING' ORDER BY created_at ASC, inserted_order ASC LIMIT 1").fetchone()
        return self._to_item(row) if row else None
    def mark_processing(self, source_comment_id: str) -> None: self._set_status(source_comment_id, "PROCESSING", error=None)
    def mark_responded(self, source_comment_id: str, response_comment_id: str) -> None:
        if not response_comment_id or not response_comment_id.strip(): raise ValueError("response_comment_id must be non-empty")
        with self._connection:
            cursor = self._connection.execute("UPDATE queue_items SET status='RESPONDED', response_comment_id=?, error=NULL WHERE source_comment_id=?", (str(response_comment_id), str(source_comment_id)))
            if cursor.rowcount != 1: raise KeyError(f"Unknown source comment ID: {source_comment_id}")
    def mark_error(self, source_comment_id: str, error: str) -> None:
        if not error or not error.strip(): raise ValueError("error must be non-empty")
        self._set_status(source_comment_id, "ERROR", error=error)
    def get(self, source_comment_id: str) -> QueueItem | None:
        row = self._connection.execute("SELECT * FROM queue_items WHERE source_comment_id=?", (str(source_comment_id),)).fetchone()
        return self._to_item(row) if row else None
    def list_items(self) -> list[QueueItem]:
        rows = self._connection.execute("SELECT * FROM queue_items ORDER BY created_at ASC, inserted_order ASC").fetchall()
        return [self._to_item(row) for row in rows]
    def close(self) -> None: self._connection.close()
    def __enter__(self) -> "BridgeState": return self
    def __exit__(self, *_: object) -> None: self.close()
    def _set_status(self, source_comment_id: str, status: str, *, error: str | None) -> None:
        if status not in VALID_STATUSES: raise ValueError(f"Unsupported status: {status}")
        with self._connection:
            cursor = self._connection.execute("UPDATE queue_items SET status=?, error=? WHERE source_comment_id=?", (status, error, str(source_comment_id)))
            if cursor.rowcount != 1: raise KeyError(f"Unknown source comment ID: {source_comment_id}")
    @staticmethod
    def _to_item(row: sqlite3.Row) -> QueueItem:
        return QueueItem(source_comment_id=row["source_comment_id"], issue_number=row["issue_number"], created_at=row["created_at"], content=row["content"], status=row["status"], response_comment_id=row["response_comment_id"], error=row["error"])
