from __future__ import annotations

import json
from dataclasses import dataclass
from typing import Any, Mapping, Sequence
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen
from urllib.parse import urlparse


class OllamaError(RuntimeError):
    """An HTTP, transport, or response error returned by Ollama."""

    def __init__(self, message: str, *, status_code: int | None = None) -> None:
        super().__init__(message)
        self.status_code = status_code


@dataclass(frozen=True)
class OllamaChatResult:
    model: str
    content: str
    done: bool
    total_duration_ns: int | None = None
    prompt_eval_count: int | None = None
    eval_count: int | None = None


class OllamaChatClient:
    """Send one non-streaming chat request to an Ollama server.

    The model name is always supplied explicitly by the caller (normally from
    BridgeConfig). This adapter has no tool-calling or execution integration.
    """

    def __init__(
        self,
        *,
        base_url: str = "http://localhost:11434",
        timeout: float = 120.0,
    ) -> None:
        if not isinstance(base_url, str) or not base_url.strip():
            raise ValueError("base_url must be a non-empty HTTP(S) URL")
        normalized_url = base_url.strip().rstrip("/")
        parsed = urlparse(normalized_url)
        if parsed.scheme not in {"http", "https"} or not parsed.netloc:
            raise ValueError("base_url must be an absolute HTTP(S) URL")
        if isinstance(timeout, bool) or not isinstance(timeout, (int, float)) or timeout <= 0:
            raise ValueError("timeout must be a positive number")
        self.base_url = normalized_url
        self.timeout = float(timeout)

    def chat(
        self,
        model: str,
        messages: Sequence[Mapping[str, str]],
        *,
        options: Mapping[str, Any] | None = None,
    ) -> OllamaChatResult:
        """Send a complete chat and return the assistant response."""
        if not isinstance(model, str) or not model.strip():
            raise ValueError("model must be a non-empty Ollama model tag")
        normalized_messages = self._validate_messages(messages)
        payload: dict[str, Any] = {
            "model": model.strip(),
            "messages": normalized_messages,
            "stream": False,
        }
        if options is not None:
            if not isinstance(options, Mapping):
                raise ValueError("options must be a mapping")
            payload["options"] = dict(options)

        request = Request(
            f"{self.base_url}/api/chat",
            data=json.dumps(payload).encode("utf-8"),
            method="POST",
            headers={
                "Accept": "application/json",
                "Content-Type": "application/json",
                "User-Agent": "igor-model-bridge",
            },
        )
        try:
            with urlopen(request, timeout=self.timeout) as response:
                raw = response.read()
        except HTTPError as exc:
            detail = exc.read().decode("utf-8", errors="replace")
            raise OllamaError(
                f"Ollama returned HTTP {exc.code}: {detail}",
                status_code=exc.code,
            ) from exc
        except (URLError, TimeoutError, OSError) as exc:
            reason = getattr(exc, "reason", None) or str(exc)
            raise OllamaError(f"Could not reach Ollama: {reason}") from exc

        if not raw:
            raise OllamaError("Ollama returned an empty response")
        try:
            data = json.loads(raw.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise OllamaError("Ollama returned invalid JSON") from exc
        if not isinstance(data, dict):
            raise OllamaError("Ollama response must be a JSON object")
        if data.get("error"):
            raise OllamaError(f"Ollama error: {data['error']}")

        message = data.get("message")
        if not isinstance(message, dict):
            raise OllamaError("Ollama response is missing the assistant message")
        content = message.get("content")
        if not isinstance(content, str) or not content.strip():
            raise OllamaError("Ollama returned empty assistant content")
        if message.get("role", "assistant") != "assistant":
            raise OllamaError("Ollama response message role was not assistant")
        done = data.get("done")
        if done is not True:
            raise OllamaError("Ollama response did not complete (done was not true)")

        response_model = data.get("model", model.strip())
        if not isinstance(response_model, str) or not response_model.strip():
            response_model = model.strip()
        return OllamaChatResult(
            model=response_model,
            content=content,
            done=True,
            total_duration_ns=self._optional_int(data, "total_duration"),
            prompt_eval_count=self._optional_int(data, "prompt_eval_count"),
            eval_count=self._optional_int(data, "eval_count"),
        )

    @staticmethod
    def _validate_messages(
        messages: Sequence[Mapping[str, str]],
    ) -> list[dict[str, str]]:
        if isinstance(messages, (str, bytes)) or not isinstance(messages, Sequence) or not messages:
            raise ValueError("messages must be a non-empty sequence")
        normalized: list[dict[str, str]] = []
        allowed_roles = {"system", "user", "assistant"}
        for index, message in enumerate(messages, start=1):
            if not isinstance(message, Mapping):
                raise ValueError(f"message {index} must be a mapping")
            role = message.get("role")
            content = message.get("content")
            if not isinstance(role, str) or role not in allowed_roles:
                raise ValueError(
                    f"message {index}: role must be one of system, user, assistant"
                )
            if not isinstance(content, str) or not content.strip():
                raise ValueError(f"message {index}: content must be non-empty text")
            normalized.append({"role": role, "content": content})
        return normalized

    @staticmethod
    def _optional_int(data: dict[str, Any], key: str) -> int | None:
        value = data.get(key)
        if isinstance(value, int) and not isinstance(value, bool) and value >= 0:
            return value
        return None
