import unittest
from unittest.mock import patch

from bridge.providers.ollama import OllamaChatClient, OllamaError


class FakeResponse:
    def __init__(self, payload):
        self.payload = payload

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc, traceback):
        return False

    def read(self):
        return self.payload


def response_payload(**overrides):
    data = {
        "model": "qwen35-local:latest",
        "message": {"role": "assistant", "content": "A considered answer."},
        "done": True,
        "total_duration": 1234,
        "prompt_eval_count": 20,
        "eval_count": 9,
    }
    data.update(overrides)
    return json.dumps(data).encode("utf-8")


class OllamaChatClientTests(unittest.TestCase):
    def setUp(self):
        self.client = OllamaChatClient(
            base_url="http://localhost:11434/",
            timeout=17,
        )
        self.messages = [{"role": "user", "content": "Explain the trade-offs."}]

    @patch("bridge.providers.ollama.urlopen")
    def test_sends_non_streaming_request_to_explicit_model(self, mock_urlopen):
        mock_urlopen.return_value = FakeResponse(response_payload())
        result = self.client.chat("qwen35-local:latest", self.messages)
        request = mock_urlopen.call_args.args[0]
        payload = json.loads(request.data.decode("utf-8"))
        self.assertEqual(request.full_url, "http://localhost:11434/api/chat")
        self.assertEqual(payload["model"], "qwen35-local:latest")
        self.assertEqual(payload["messages"], self.messages)
        self.assertIs(payload["stream"], False)
        self.assertEqual(mock_urlopen.call_args.kwargs["timeout"], 17)
        self.assertEqual(result.content, "A considered answer.")
        self.assertEqual(result.model, "qwen35-local:latest")
        self.assertEqual(result.eval_count, 9)

    @patch("bridge.providers.ollama.urlopen")
    def test_passes_generation_options(self, mock_urlopen):
        mock_urlopen.return_value = FakeResponse(response_payload())
        self.client.chat("gemma3:4b", self.messages, options={"temperature": 0.2})
        payload = json.loads(mock_urlopen.call_args.args[0].data.decode("utf-8"))
        self.assertEqual(payload["options"], {"temperature": 0.2})

    def test_rejects_invalid_server_settings(self):
        with self.assertRaises(ValueError):
            OllamaChatClient(base_url="localhost:11434")
        with self.assertRaises(ValueError):
            OllamaChatClient(timeout=0)

    def test_rejects_invalid_model_or_messages_before_network_call(self):
        with patch("bridge.providers.ollama.urlopen") as mock_urlopen:
            with self.assertRaises(ValueError):
                self.client.chat("", self.messages)
            with self.assertRaises(ValueError):
                self.client.chat("model", [])
            with self.assertRaises(ValueError):
                self.client.chat("model", [{"role": "tool", "content": "x"}])
            with self.assertRaises(ValueError):
                self.client.chat("model", [{"role": "user", "content": " "}])
            mock_urlopen.assert_not_called()

    @patch("bridge.providers.ollama.urlopen")
    def test_rejects_invalid_json(self, mock_urlopen):
        mock_urlopen.return_value = FakeResponse(b"not-json")
        with self.assertRaisesRegex(OllamaError, "invalid JSON"):
            self.client.chat("model", self.messages)

    @patch("bridge.providers.ollama.urlopen")
    def test_rejects_empty_and_incomplete_responses(self, mock_urlopen):
        for raw in (b"", b'{}', response_payload(done=False),
                    response_payload(message={"role": "assistant", "content": ""})):
            mock_urlopen.return_value = FakeResponse(raw)
            with self.subTest(raw=raw):
                with self.assertRaises(OllamaError):
                    self.client.chat("model", self.messages)

    @patch("bridge.providers.ollama.urlopen")
    def test_surfaces_ollama_json_error(self, mock_urlopen):
        mock_urlopen.return_value = FakeResponse(
            json.dumps({"error": "model not found"}).encode()
        )
        with self.assertRaisesRegex(OllamaError, "model not found"):
            self.client.chat("missing-model", self.messages)

    @patch("bridge.providers.ollama.urlopen")
    def test_uses_requested_model_if_response_omits_model(self, mock_urlopen):
        data = json.loads(response_payload())
        data.pop("model")
        mock_urlopen.return_value = FakeResponse(json.dumps(data).encode())
        result = self.client.chat("configured-tag", self.messages)
        self.assertEqual(result.model, "configured-tag")


if __name__ == "__main__":
    unittest.main()
