from types import SimpleNamespace
from unittest.mock import patch

from bridge.config import BridgeConfig, ModelRoute
from bridge.runner import build_parser, main


class RunnerTests(unittest.TestCase):
    def setUp(self):
        self.config = BridgeConfig(
            repository="owner/repo",
            token_env="GITHUB_TOKEN",
            igor_username="igor-user",
            ollama_base_url="http://localhost:11434",
            ollama_timeout_seconds=30,
            models=(
                ModelRoute("qwen", 11, "ollama", "qwen35-local:latest"),
                ModelRoute("gemma", 12, "ollama", "gemma3:4b"),
            ),
        )

    def test_default_mode_is_poll_only(self):
        args = build_parser().parse_args([])
        self.assertFalse(args.execute)
        self.assertIsNone(args.model_id)

    def test_execute_requires_explicit_model_id(self):
        with self.assertRaises(SystemExit):
            main(["--execute"])

    @patch.dict("os.environ", {"GITHUB_TOKEN": "test-token"})
    @patch("bridge.runner.BridgeWorker")
    @patch("bridge.runner.BridgeState")
    @patch("bridge.runner.OllamaChatClient")
    @patch("bridge.runner.GitHubIssuesTransport")
    @patch("bridge.runner.load_config")
    def test_default_run_only_polls_and_never_processes(
        self, load_config, github_cls, ollama_cls, state_cls, worker_cls
    ):
        load_config.return_value = self.config
        state = state_cls.return_value
        state.list_items.return_value = []

        self.assertEqual(main([]), 0)
        worker_cls.return_value.poll.assert_called_once_with(model_id=None)
        worker_cls.return_value.run_once.assert_not_called()
        state.close.assert_called_once()

    @patch.dict("os.environ", {"GITHUB_TOKEN": "test-token"})
    @patch("bridge.runner.BridgeWorker")
    @patch("bridge.runner.BridgeState")
    @patch("bridge.runner.OllamaChatClient")
    @patch("bridge.runner.GitHubIssuesTransport")
    @patch("bridge.runner.load_config")
    def test_execute_processes_at_most_one_selected_model_item(
        self, load_config, github_cls, ollama_cls, state_cls, worker_cls
    ):
        load_config.return_value = self.config
        worker_cls.return_value.run_once.return_value = SimpleNamespace(
            status="responded",
            source_comment_id="123",
            issue_number=11,
            model_id="qwen",
            response_comment_id="456",
        )

        self.assertEqual(main(["--execute", "--model-id", "qwen"]), 0)
        worker_cls.return_value.run_once.assert_called_once_with(model_id="qwen")
        worker_cls.return_value.poll.assert_not_called()
        state_cls.return_value.close.assert_called_once()


if __name__ == "__main__":
    unittest.main()
